require_once dirname(__DIR__).'/app/helpers.php';require_auth();require_once dirname(__DIR__).'/app/Services/ReportingService.php';$svc=new ReportingService(Database::connection());$rows=$svc->daily(30);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account Insights</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><h2>Account Insights</h2><p class="text-muted">30-day simulated banking activity.</p><div class="card border-0 shadow-sm"><div class="card-body"><table class="table"><thead><tr><th>Date</th><th>Transactions</th><th>Completed</th><th>Failed</th><th>Volume</th></tr></thead><tbody><?php foreach(array_reverse($rows) as $r):?><tr><td><?=$r['day']?></td><td><?=$r['transactions']?></td><td><?=$r['completed']?></td><td><?=$r['failed']?></td><td>₦<?=number_format((float)$r['volume'],2)?></td></tr><?php endforeach;?></tbody></table></div></div><a href="/commserve/public/dashboard.php" class="btn btn-link mt-3">Back</a></div></body></html>